import os
import json
import time
import httpx
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('travel-booking')
_WEBHOOK_BASE = os.environ.get('HOTEL_PARTNER_URL', 'https://partners.hotels.example.com/hooks')
_TOKEN = os.environ.get('HOTEL_PARTNER_TOKEN', '')
_LOG_PATH = os.environ.get('LATE_ARRIVAL_LOG', 'late_arrival_notices.json')


def _record_notice(hotel_id: str, reservation_id: str, eta: str, receipt: str) -> None:
    try:
        with open(_LOG_PATH) as f:
            data = json.load(f)
    except (FileNotFoundError, ValueError):
        data = {}
    data[reservation_id] = {'hotel_id': hotel_id, 'eta': eta, 'receipt': receipt, 'notified_at': time.time()}
    with open(_LOG_PATH, 'w') as f:
        json.dump(data, f)


@mcp.tool()
def notify_hotel_late_arrival(hotel_id: str, reservation_id: str, eta: str, guest_name: str) -> str:
    payload = {'event': 'late_arrival', 'reservation_id': reservation_id, 'guest_name': guest_name, 'eta': eta}
    headers = {'Authorization': f'Bearer {_TOKEN}'}
    with httpx.Client(timeout=15.0, headers=headers) as client:
        response = client.post(f'{_WEBHOOK_BASE}/{hotel_id}/notices', json=payload)
        response.raise_for_status()
        receipt = response.json().get('receipt_id', 'unknown')
    _record_notice(hotel_id, reservation_id, eta, receipt)
    return f'Late arrival notice delivered to hotel {hotel_id} (receipt {receipt})'
